<template>
  <div class="flex flex-col gap-2">
    <div class="flex items-center gap-2">
      <Badge v-if="state.provider_status" :variant="getProviderStatus(state.provider_status).variant">
        {{ getProviderStatus(state.provider_status).label }}
      </Badge>
      <span v-else class="text-muted-foreground">—</span>
    </div>

    <div v-if="timestampForStatus" class="text-sm">
      <span class="text-muted-foreground">{{ timestampForStatus.label }}:</span>
      <span class="ml-1">{{ formatDateTzToFormat(timestampForStatus.value, 'MM/dd/yyyy, hh:mm aaa', timezone) }}</span>
    </div>

    <div v-if="state.fail_reasons.length > 0" class="text-sm">
      <p class="text-muted-foreground">Fail reasons</p>
      <ul class="list-disc pl-5">
        <li v-for="reason in state.fail_reasons" :key="reason">{{ reason }}</li>
      </ul>
    </div>
  </div>
</template>

<script setup lang="ts">
import type { ContractSigningStatePublicV2 } from '~/client';
import { getProviderStatus } from '~/constants/contracts/providerStatusConfig';
import { formatDateTzToFormat } from '~/utils/formatDateToFormat';

const props = defineProps<{
  state: ContractSigningStatePublicV2;
  timezone: string | undefined;
}>();

const timestampForStatus = computed<{ label: string; value: string } | null>(() => {
  const { provider_status, sent_at, opened_at, signed_at } = props.state;
  if (provider_status === 'signed' && signed_at) return { label: 'Signed at', value: signed_at };
  if (provider_status === 'opened' && opened_at) return { label: 'Opened at', value: opened_at };
  if (provider_status === 'sent' && sent_at) return { label: 'Sent at', value: sent_at };
  return null;
});
</script>
