import { terminateContract, type TerminateContractRequest, type TerminateContractResponse2 } from '~/client';

export const useTerminateContract = defineMutation(() => {
  const queryCache = useQueryCache();

  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (body: TerminateContractRequest): Promise<TerminateContractResponse2> =>
      terminateContract({
        composable: '$fetch',
        body,
      }),
    onSuccess: async () => {
      queryCache.invalidateQueries({ key: ['contracts-list'] });
      queryCache.invalidateQueries({ key: ['contract'] });
      showToastSuccess('Contract terminated successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    terminateContractMutation: mutateAsync,
    isTerminating: computed(() => asyncStatus.value === 'loading'),
  };
});
