import type { ProviderStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge';

interface ProviderStatusEntry {
  label: string;
  variant: BadgeVariants;
}

export const providerStatusConfig: Record<ProviderStatus, ProviderStatusEntry> = {
  sent: { label: 'Sent', variant: 'default' },
  opened: { label: 'Viewed', variant: 'info' },
  signed: { label: 'Signed', variant: 'success' },
};

const defaultStatus: ProviderStatusEntry = { label: '', variant: 'default' };

export function getProviderStatus(status: ProviderStatus): ProviderStatusEntry {
  return providerStatusConfig[status] ?? { ...defaultStatus, label: snakeCaseToCapitalizedCase(status) };
}
