<template>
  <AppLoader v-if="isLoading" subject="contract" />
  <AppError v-else-if="error" title="Failed to load contract" :error="error" />
  <AppEmpty v-else-if="!contract" subject="contract details" />
  <section v-else class="flex flex-col gap-4">
    <div class="flex flex-wrap items-center gap-3">
      <PageTitle title="Contract details" />
      <Badge :variant="typeLabel.variant">
        {{ typeLabel.name }}
      </Badge>
      <Badge :variant="statusLabel.variant">
        {{ statusLabel.name }}
      </Badge>
    </div>
    <GoBackButton subject="contracts" :fallback-to="{ name: 'contracts' }" />

    <div class="grid grid-cols-3 gap-4 md:gap-5">
      <div class="flex flex-col gap-4 col-span-3 xl:col-span-2 order-2 xl:order-1 md:gap-5">
        <Card>
          <CardHeader>
            <CardTitle>Summary</CardTitle>
          </CardHeader>
          <CardContent class="grid grid-cols-1 sm:grid-cols-2 gap-4">
            <LabeledEntityUser v-if="isAdminOrManager" :user-id="contract.canvasser_id" />
            <LabeledEntityProject
              v-if="contract.type === 'assignment'"
              label="Project"
              :project-id="contract.project_id"
            />
            <LabeledEntityDate label="Created at" :date="contract.created_at" />
            <template v-if="contract.type === 'assignment'">
              <LabeledValueIcon
                label="Assignment type"
                :value="assignmentTypeLabel[contract.assignment_type] ?? contract.assignment_type"
                :icon="BriefcaseBusinessIcon"
              />
              <LabeledValueIcon label="Pay rate" :value="contract.pay_rate" :icon="BanknoteIcon" />
            </template>
            <LabeledValueIcon
              v-if="contract.type === 'w9' && contract.parsed_ssn"
              label="SSN"
              :value="contract.parsed_ssn"
              :icon="IdCardIcon"
            />
            <LabeledValueIcon label="Contract ID" :value="contract.provider_side_id" :icon="HashIcon" />
          </CardContent>
        </Card>

        <ContractsDetailsSigningStateCard
          :admin-state="contract.type === 'assignment' ? contract.admin_state : undefined"
          :canvasser-state="contract.canvasser_state"
          :timezone="timezone"
        />
      </div>

      <div class="col-span-3 xl:col-span-1 order-1 xl:order-2 h-fit">
        <Card>
          <CardHeader>
            <CardTitle>Actions</CardTitle>
          </CardHeader>
          <CardContent class="flex flex-col gap-3">
            <a
              v-if="bothPartiesSigned && contract.pdf_s3_url"
              :href="contract.pdf_s3_url"
              target="_blank"
              rel="noopener noreferrer"
            >
              <Button class="w-full" variant="outline" :prepend-icon="DownloadIcon">Download signed PDF</Button>
            </a>

            <a
              v-if="
                canStillSign &&
                contract.type === 'assignment' &&
                isAdmin &&
                !signedByAdmin &&
                contract.admin_state.sign_url
              "
              :href="contract.admin_state.sign_url"
              target="_blank"
              rel="noopener noreferrer"
            >
              <Button class="w-full" variant="outline" :prepend-icon="ExternalLinkIcon">Open admin sign URL</Button>
            </a>

            <a
              v-if="canStillSign && isCanvasser && !signedByCanvasser && contract.canvasser_state.sign_url"
              :href="contract.canvasser_state.sign_url"
              target="_blank"
              rel="noopener noreferrer"
            >
              <Button class="w-full" variant="outline" :prepend-icon="ExternalLinkIcon">Open canvasser sign URL</Button>
            </a>

            <Dialog v-if="canTerminate" v-model:open="isTerminateDialogOpen">
              <DialogTrigger as-child>
                <Button class="w-full" variant="destructive" :prepend-icon="XIcon">Terminate contract</Button>
              </DialogTrigger>
              <DialogContent>
                <DialogHeader>
                  <DialogTitle>Terminate contract</DialogTitle>
                  <DialogDescription>
                    This will terminate the canvasser's assignment on this project. This action cannot be undone.
                  </DialogDescription>
                </DialogHeader>
                <DialogFooter class="flex flex-row justify-end gap-2">
                  <Button variant="outline" :disabled="isTerminating" @click="isTerminateDialogOpen = false">
                    Cancel
                  </Button>
                  <Button variant="destructive" :loading="isTerminating" @click="onTerminate">Terminate</Button>
                </DialogFooter>
              </DialogContent>
            </Dialog>

            <p v-if="noActionMessage" class="text-sm text-muted-foreground">{{ noActionMessage }}</p>
          </CardContent>
        </Card>
      </div>
    </div>
  </section>
</template>

<script setup lang="ts">
import {
  BanknoteIcon,
  BriefcaseBusinessIcon,
  DownloadIcon,
  ExternalLinkIcon,
  HashIcon,
  IdCardIcon,
  XIcon,
} from 'lucide-vue-next';
import { getContractDetailsV2, type AssignmentType, type GetContractDetailsV2Response } from '~/client';
import { getContractStatusLabel } from '~/constants/contracts/contractStatusConfig';
import { getContractTypeLabel } from '~/constants/contracts/contractTypeConfig';

definePageMeta({
  roles: ['admin', 'manager', 'canvasser'],
  backLabel: 'contract',
});

const route = useRoute('contracts-id');
const contractId = computed(() => route.params.id?.toString() || '');

const { isAdmin, isAdminOrManager, isCanvasser, timezone } = useUserRole();

const {
  data: contract,
  error,
  isLoading,
} = useQuery({
  key: () => ['contract', contractId.value],
  query: (): Promise<GetContractDetailsV2Response> =>
    getContractDetailsV2({ composable: '$fetch', path: { contract_id: contractId.value } }),
  enabled: () => !!contractId.value && route.name === 'contracts-id',
});

const { terminateContractMutation, isTerminating } = useTerminateContract();

const isTerminateDialogOpen = ref(false);

useHead({
  title: computed(() => (contract.value ? `Contract ${contract.value.provider_side_id}` : 'Contract')),
});

const assignmentTypeLabel: Record<AssignmentType, string> = {
  local: 'Local',
  quick_response_force: 'Quick response force',
};

const canTerminate = computed(
  () =>
    isAdminOrManager.value &&
    contract.value &&
    contract.value.type === 'assignment' &&
    (contract.value.status === 'active' || contract.value.status === 'pending')
);

const canStillSign = computed(() => contract.value?.status === 'pending');

const signedByAdmin = computed<boolean | null>(() => {
  if (!contract.value || contract.value.type !== 'assignment') return null;
  return contract.value.admin_state.signed;
});

const signedByCanvasser = computed(() => contract.value?.canvasser_state.signed ?? false);

const bothPartiesSigned = computed(() => {
  if (!contract.value) return false;
  if (contract.value.type === 'w9') return signedByCanvasser.value;
  return signedByCanvasser.value && signedByAdmin.value === true;
});

const statusLabel = computed(() => {
  if (!contract.value) return { name: '', variant: 'default' as const };
  return getContractStatusLabel(
    contract.value.status,
    contract.value.type,
    signedByAdmin.value,
    signedByCanvasser.value
  );
});

const typeLabel = computed(() => {
  if (!contract.value) return { name: '', variant: 'default' as const };
  return getContractTypeLabel(contract.value.type);
});

const noActionMessage = computed<string | null>(() => {
  if (!contract.value) return null;

  if (bothPartiesSigned.value && contract.value.pdf_s3_url) return null;
  if (
    canStillSign.value &&
    contract.value.type === 'assignment' &&
    isAdmin.value &&
    !signedByAdmin.value &&
    contract.value.admin_state.sign_url
  )
    return null;
  if (canStillSign.value && isCanvasser.value && !signedByCanvasser.value && contract.value.canvasser_state.sign_url)
    return null;
  if (canTerminate.value) return null;

  if (bothPartiesSigned.value && !contract.value.pdf_s3_url) {
    return 'Signed PDF is being prepared. Please check back shortly.';
  }

  if (isCanvasser.value) {
    if (contract.value.status === 'terminated') return 'This contract has been terminated.';
    if (contract.value.status === 'failed') return 'This contract failed validation and is no longer active.';
    if (signedByCanvasser.value) return 'You have signed this contract. Awaiting admin signature.';
    if (contract.value.type === 'assignment' && !signedByAdmin.value) {
      return "Waiting for the admin's signature.";
    }
    return 'Sign URL is not available yet. Please check back shortly.';
  }

  return 'No actions available for this contract.';
});

async function onTerminate() {
  if (!contract.value || contract.value.type !== 'assignment') return;
  try {
    await terminateContractMutation({
      canvasser_id: contract.value.canvasser_id,
      project_id: contract.value.project_id,
    });
    isTerminateDialogOpen.value = false;
  } catch {
    // error toast handled in mutation
  }
}
</script>
